{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Indomethacin, a high-transfer analogue sharing the chloroindole and methoxyaryl motifs, has an absolute oral bioavailability of 98% in adults, directly supporting F >=20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Rigosertib, a high-transfer analogue, showed 35% absolute oral bioavailability after a fasting oral dose, supporting F >=20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Omeprazole, a high-transfer benzimidazole analogue, has an absolute oral bioavailability of about 30-40%, supporting F >=20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Loratadine, a high-transfer tricyclic analogue, is reported to have good oral bioavailability in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "GDC-0810, a structurally related molecule with a chloro/fluoro aromatic system, was predicted to have approximately 45% absolute oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Alfuzosin, a high-transfer analogue, has a mean absolute oral bioavailability of 64.5% in healthy subjects, supporting F >=20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Colchicine, a high-transfer analogue, has a mean absolute oral bioavailability of 44%, supporting F >=20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple high-transfer experimental analogues consistently show absolute oral bioavailability above the 20% threshold, outweighing the uncertain physicochemical prior of low bioavailability. The prediction is therefore high, with moderate confidence due to lack of direct query data and the query's larger polar surface area.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule.",
    "The analogue set does not fully cover the query's high molecular weight and TPSA, so solubility-limited absorption remains a possible liability.",
    "Some analogue records show condition-dependent low F (e.g., indomethacin in infants, rigosertib fed), but these are not representative of the query context."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

